import assert from 'node:assert/strict'
import { spawn, execFileSync } from 'node:child_process'
import { existsSync, rmSync, writeFileSync } from 'node:fs'

const BASE='http://127.0.0.1:4173/'
const SOURCE_SHA='3335c5186df08bba5034d5d8e5b920ba5de6b16d'
const KEY='skipjack_tuna'
const LABEL='가다랑어(Skipjack tuna)'
const EXPECTED_IDS=['product_1dbe295704557258','product_b41eecd6fdc295e8','product_c5aec16eea0cc24d','product_c874d6b2acf9ea6b','product_d99605a0a35f0fb7'].sort()
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms))

class Cdp{constructor(url){this.url=url;this.ws=null;this.id=1;this.pending=new Map()}async connect(){this.ws=new WebSocket(this.url);await new Promise((res,rej)=>{const t=setTimeout(()=>rej(new Error('ws timeout')),15000);this.ws.addEventListener('open',()=>{clearTimeout(t);res()},{once:true});this.ws.addEventListener('error',()=>rej(new Error('ws error')),{once:true})});this.ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(!m.id)return;const p=this.pending.get(m.id);if(!p)return;this.pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result)});for(const m of ['Page.enable','Runtime.enable'])await this.send(m)}send(method,params={}){const id=this.id++;return new Promise((res,rej)=>{this.pending.set(id,{resolve:res,reject:rej});this.ws.send(JSON.stringify({id,method,params}))})}async eval(expression){const r=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result?.value}async wait(expression,label,ms=45000){const end=Date.now()+ms;while(Date.now()<end){try{if(await this.eval(`Boolean(${expression})`))return}catch{}await sleep(120)}throw new Error(`timeout ${label}`)}async nav(url){await this.send('Page.navigate',{url});await this.wait(`document.readyState==='complete'`,'ready');await this.wait(`document.querySelector('#root')&&document.body.innerText.length>0`,'root')}async viewport(w,h){await this.send('Emulation.setDeviceMetricsOverride',{width:w,height:h,deviceScaleFactor:1,mobile:w<=390})}async shot(path){const r=await this.send('Page.captureScreenshot',{format:'png',fromSurface:true,captureBeyondViewport:false});writeFileSync(path,Buffer.from(r.data,'base64'))}close(){try{this.ws?.close()}catch{}}}
async function launch(){const bin='/usr/bin/google-chrome';assert.ok(existsSync(bin));const version=execFileSync(bin,['--version'],{encoding:'utf8'}).trim();const port=9970+(process.pid%20);const dir=`/tmp/pr19-final-${process.pid}`;rmSync(dir,{recursive:true,force:true});const proc=spawn(bin,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore'});for(let i=0;i<220;i++){try{const pages=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();const p=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl);if(p)return{version,proc,dir,c:new Cdp(p.webSocketDebuggerUrl)}}catch{}await sleep(100)}throw new Error('chrome timeout')}
const visibleExpr=(s)=>`(()=>{const n=document.querySelector(${JSON.stringify(s)});if(!n)return false;const r=n.getBoundingClientRect(),c=getComputedStyle(n);return c.display!=='none'&&c.visibility!=='hidden'&&r.width>0&&r.height>0&&r.bottom>0&&r.top<innerHeight})()`
async function click(c,selector,text=null){const p=await c.eval(`(()=>{const nodes=[...document.querySelectorAll(${JSON.stringify(selector)})];const n=${text===null?'nodes[0]':`nodes.find(x=>x.textContent?.trim().includes(${JSON.stringify(text)}))`};if(!n)return null;n.scrollIntoView({block:'center',inline:'nearest'});const r=n.getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2}})()`);assert.ok(p,`missing click ${text??selector}`);await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:p.x,y:p.y,button:'left',clickCount:1});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x,y:p.y,button:'left',clickCount:1});await sleep(220)}
async function setInput(c,selector,value){const ok=await c.eval(`(()=>{const n=document.querySelector(${JSON.stringify(selector)});if(!n)return false;const set=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;set.call(n,${JSON.stringify(value)});n.dispatchEvent(new Event('input',{bubbles:true}));return true})()`);assert.equal(ok,true,`missing input ${selector}`);await sleep(250)}
async function resultIds(c){return JSON.parse(await c.eval(`JSON.stringify([...document.querySelectorAll('.research-result-card')].map(n=>n.dataset.productId).filter(Boolean).sort())`))}
async function waitResults(c){await c.wait(`document.querySelectorAll('.research-result-card').length>0`,'results')}
async function waitVisibleImages(c,ms=12000){const end=Date.now()+ms;while(Date.now()<end){const settled=await c.eval(`(()=>{const imgs=[...document.querySelectorAll('.research-result-image')].filter(n=>{const r=n.getBoundingClientRect();return r.bottom>0&&r.top<innerHeight});return imgs.length===0||imgs.every(n=>n.complete)})()`);if(settled)break;await sleep(150)}await sleep(350);return c.eval(`(()=>[...document.querySelectorAll('.research-result-image')].filter(n=>{const r=n.getBoundingClientRect();return r.bottom>0&&r.top<innerHeight}).slice(0,6).map(n=>({src:n.currentSrc||n.src,complete:n.complete,naturalWidth:n.naturalWidth,naturalHeight:n.naturalHeight,visibility:getComputedStyle(n).visibility})))()`)}
async function measure(c){return c.eval(`(()=>{const q=s=>document.querySelector(s);const rect=n=>{if(!n)return null;const r=n.getBoundingClientRect();return{x:+r.x.toFixed(2),y:+r.y.toFixed(2),width:+r.width.toFixed(2),height:+r.height.toFixed(2),bottom:+r.bottom.toFixed(2),right:+r.right.toFixed(2)}};const css=n=>{if(!n)return null;const s=getComputedStyle(n);return{display:s.display,visibility:s.visibility,position:s.position,height:s.height,minHeight:s.minHeight,gridTemplateRows:s.gridTemplateRows,gridAutoRows:s.gridAutoRows}};const shell=q('.research-shell'),entry=q('.mobile-refine-entry'),button=q('.mobile-refine-entry button'),workspace=q('.research-workspace'),panel=q('#mobile-recipe-refine-panel'),search=q('.recipe-search'),refine=q('.refine-title'),nav=q('.mode-nav'),criteria=q('.criteria-bar');return{innerWidth,innerHeight,docWidth:document.documentElement.scrollWidth,docHeight:document.documentElement.scrollHeight,scrollY,shell:{rect:rect(shell),css:css(shell)},topbar:{rect:rect(q('.research-topbar')),css:css(q('.research-topbar'))},nav:{rect:rect(nav),css:css(nav)},criteria:{rect:rect(criteria),css:css(criteria)},entry:{rect:rect(entry),css:css(entry)},button:{rect:rect(button),css:css(button),expanded:button?.getAttribute('aria-expanded')??null},workspace:{rect:rect(workspace),css:css(workspace)},panel:{rect:rect(panel),css:css(panel)},refineTitle:{rect:rect(refine),css:css(refine)},search:{rect:rect(search),css:css(search)},results:{rect:rect(q('.research-results')),css:css(q('.research-results'))},summary:{rect:rect(q('.condition-summary')),css:css(q('.condition-summary'))},summaryActions:{rect:rect(q('.summary-actions')),css:css(q('.summary-actions'))},activeClass:document.activeElement?.className||document.activeElement?.tagName||null,activeIsSearch:document.activeElement===search,activeIsToggle:document.activeElement===button,panelCount:document.querySelectorAll('#mobile-recipe-refine-panel').length,searchCount:document.querySelectorAll('.recipe-search').length}})()`)}
function assertOpenLayout(m,label){assert.equal(m.docWidth,m.innerWidth,`${label} horizontal overflow`);assert.ok(m.button?.rect?.height>=34&&m.button.rect.height<=50,`${label} button stretched: ${m.button?.rect?.height}`);assert.ok(m.entry?.rect?.height>=34&&m.entry.rect.height<=50,`${label} entry stretched: ${m.entry?.rect?.height}`);assert.ok(m.workspace?.rect&&m.entry?.rect,`${label} missing layout rects`);const gap=+(m.workspace.rect.y-m.entry.rect.bottom).toFixed(2);assert.ok(gap>=13&&gap<=15.5,`${label} workspace gap ${gap}`);assert.ok(m.panel?.rect&&Math.abs(m.panel.rect.y-m.workspace.rect.y)<=1,`${label} panel not attached to workspace`);assert.equal(m.results?.css?.display,'none',`${label} results visible while refining`);assert.equal(m.summary?.css?.display,'none',`${label} summary visible while refining`);assert.equal(m.summaryActions?.css?.display,'none',`${label} summary actions visible while refining`);assert.equal(m.activeIsSearch,true,`${label} search should own focus`);if(m.nav?.rect&&m.criteria?.rect)assert.ok(m.nav.rect.bottom<=m.criteria.rect.y+0.5,`${label} top nav overlap`);const tracks=(m.shell.css.gridTemplateRows||'').trim().split(/\s+/);assert.equal(tracks.length,4,`${label} shell should expose four explicit rows`);return{workspaceGap:gap}}
async function reachApplied(c,w,h,url='?view=workspace&applied=1'){await c.viewport(w,h);await c.nav(BASE+url);await waitResults(c);await c.eval('window.scrollTo(0,0)');await sleep(220)}
async function openRefine(c){await click(c,'.mobile-refine-entry button','더 좁혀보기');await c.wait(`${visibleExpr('#mobile-recipe-refine-panel .recipe-search')}&&document.querySelector('.mobile-refine-entry button')?.getAttribute('aria-expanded')==='true'`,'open refine');await c.eval('window.scrollTo(0,0)');await sleep(220)}

async function runMobileFlow(c,w,h){const prefix=`candidate-${SOURCE_SHA.slice(0,8)}-${w}x${h}`;await reachApplied(c,w,h);const imagesBefore=await waitVisibleImages(c);const closed=await measure(c);assert.ok(closed.button?.rect?.height>=34&&closed.button.rect.height<=50,`${w} closed button height`);await c.shot(`qa-artifacts/${prefix}-list.png`);await openRefine(c);await setInput(c,'.recipe-search','');const noSearch=await measure(c);const noSearchDerived=assertOpenLayout(noSearch,`${w}x${h} no-search`);await c.shot(`qa-artifacts/${prefix}-open-no-search.png`);
  await setInput(c,'.recipe-search','가다랑어');await c.wait(`[...document.querySelectorAll('.recipe-detail-grid .choice')].filter(x=>getComputedStyle(x).display!=='none').length===1`,'Korean one result');assert.equal((await c.eval(`document.querySelector('.recipe-detail-grid .choice')?.textContent?.trim()`)),LABEL,`${w} Korean search mismatch`);
  await setInput(c,'.recipe-search',KEY);await c.wait(`document.querySelectorAll('.recipe-detail-grid .choice').length===1`,'raw one result');const oneResult=await measure(c);const oneDerived=assertOpenLayout(oneResult,`${w}x${h} one-result`);await c.shot(`qa-artifacts/${prefix}-open-one-result.png`);
  await click(c,'.recipe-detail-grid .choice',LABEL);await c.wait(`new URLSearchParams(location.search).get('recipeDetails')==='${KEY}'`,'selected URL');await c.wait(`${visibleExpr('.selected-refinement')}`,'selected chip');assert.deepEqual(await resultIds(c),EXPECTED_IDS,`${w} raw-key product IDs changed`);const selected=await measure(c);const selectedDerived=assertOpenLayout(selected,`${w}x${h} selected`);await c.shot(`qa-artifacts/${prefix}-open-selected.png`);
  await click(c,'.mobile-refine-entry button','목록으로 돌아가기');await c.wait(`document.querySelector('.mobile-refine-entry button')?.getAttribute('aria-expanded')==='false'&&${visibleExpr('.research-results')}`,'close refine');let afterClose=await measure(c);assert.equal(afterClose.activeIsToggle,true,`${w} close focus not restored`);await waitVisibleImages(c);await c.shot(`qa-artifacts/${prefix}-selected-list.png`);
  await click(c,'.mobile-refine-entry button','더 좁혀보기');await c.wait(`${visibleExpr('.selected-refinement')}`,'reopen selected');assert.equal((await measure(c)).activeIsSearch,true,`${w} reopen focus not search`);await click(c,'.selected-refinement',LABEL);await c.wait(`!new URLSearchParams(location.search).has('recipeDetails')`,'deselect URL');assert.ok((await resultIds(c)).length>EXPECTED_IDS.length,`${w} deselect did not broaden results`);await click(c,'.mobile-refine-entry button','목록으로 돌아가기');await c.wait(`${visibleExpr('.research-results')}`,'results after deselect');afterClose=await measure(c);assert.equal(afterClose.activeIsToggle,true,`${w} final close focus not toggle`);return{closed,noSearch,noSearchDerived,oneResult,oneDerived,selected,selectedDerived,imagesBefore}}

async function measureExtraViewport(c,w,h){await reachApplied(c,w,h);await openRefine(c);await setInput(c,'.recipe-search','');const m=await measure(c);const derived=assertOpenLayout(m,`${w}x${h} extra`);return{measure:m,derived}}

async function checkConditionEdit(c){await c.viewport(390,900);await c.nav(BASE+'?view=workspace');await c.wait(`${visibleExpr('.condition-actions')}`,'condition editor');await c.eval('window.scrollTo(0,0)');const m=await measure(c);assert.equal(await c.eval(`Boolean(document.querySelector('.mobile-refine-entry'))`),false,'mobile refine entry should not render while editing primary conditions');assert.notEqual(m.panel?.css?.display,'none','condition panel missing');await c.shot('qa-artifacts/candidate-390-condition-edit.png');return m}
async function checkQuickView(c){await reachApplied(c,390,900);await waitVisibleImages(c);await click(c,'.research-result-card');await c.wait(`${visibleExpr('.research-quick-view')}`,'quick view');const m=await measure(c);assert.equal(await c.eval(`Boolean(document.querySelector('.mobile-refine-entry'))`),false,'mobile refine entry should not render in quick view');assert.ok((await c.eval(`document.querySelector('.research-shell')?.classList.contains('is-inspecting')`)),'quick view shell not inspecting');await c.shot('qa-artifacts/candidate-390-quick-view.png');return m}
async function checkBreakpoints(c){const url=`?view=workspace&applied=1&recipeDetails=${KEY}`;await reachApplied(c,980,900,url);await openRefine(c);const m980=await measure(c);assertOpenLayout(m980,'980 open');await c.shot('qa-artifacts/candidate-980-open.png');await click(c,'.mobile-refine-entry button','목록으로 돌아가기');await c.wait(`document.querySelector('.mobile-refine-entry button')?.getAttribute('aria-expanded')==='false'`,'980 close');assert.equal((await measure(c)).activeIsToggle,true,'980 toggle focus before resize');await c.viewport(981,900);await sleep(350);const m981=await measure(c);assert.equal(m981.entry?.css?.display,'none','981 mobile entry visible');assert.notEqual(m981.panel?.css?.display,'none','981 desktop panel hidden');assert.notEqual(m981.results?.css?.display,'none','981 desktop results hidden');assert.equal(m981.activeIsSearch,true,'981 focus not moved to desktop recipe search');assert.equal(m981.panelCount,1,'981 duplicate panel');assert.equal(m981.searchCount,1,'981 duplicate search');await c.shot('qa-artifacts/candidate-981-desktop.png');await c.viewport(1440,900);await sleep(350);const m1440=await measure(c);assert.equal(m1440.entry?.css?.display,'none','1440 mobile entry visible');assert.notEqual(m1440.panel?.css?.display,'none','1440 panel hidden');assert.notEqual(m1440.results?.css?.display,'none','1440 results hidden');assert.equal(m1440.panelCount,1,'1440 duplicate panel');assert.equal(m1440.searchCount,1,'1440 duplicate search');await c.shot('qa-artifacts/candidate-1440-desktop.png');return{m980,m981,m1440}}

const {version,proc,dir,c}=await launch();const report={browserVersion:version,sourceSha:SOURCE_SHA,expectedIds:EXPECTED_IDS,checks:{}};try{await c.connect();report.checks.mobile360x844=await runMobileFlow(c,360,844);report.checks.mobile390x900=await runMobileFlow(c,390,900);report.checks.extra360x900=await measureExtraViewport(c,360,900);report.checks.extra390x844=await measureExtraViewport(c,390,844);report.checks.conditionEdit=await checkConditionEdit(c);report.checks.quickView=await checkQuickView(c);report.checks.breakpoints=await checkBreakpoints(c);writeFileSync('qa-artifacts/report.json',JSON.stringify(report,null,2));console.log('PR19_GRID_FIX_QA PASS')}catch(e){writeFileSync('qa-artifacts/report.json',JSON.stringify({...report,error:String(e),url:await c.eval('location.href').catch(()=>null),body:await c.eval('document.body.innerText').catch(()=>null)},null,2));await c.shot('qa-artifacts/failure.png').catch(()=>{});throw e}finally{c.close();proc.kill('SIGTERM');await sleep(200);if(proc.exitCode==null)proc.kill('SIGKILL');rmSync(dir,{recursive:true,force:true})}
